#!/usr/bin/env python3
import sys, unicodedata, re, os

def is_decimal(ch): return unicodedata.category(ch) == 'Nd'
def is_space(ch): return ch.isspace()
def is_word(ch):
    cat = unicodedata.category(ch)
    return cat.startswith('L') or cat.startswith('M') or cat=='Nd' or cat=='Pc' or ch=='_'

def escape_literal(ch):
    if ch == '\t': return r'\t'
    if ch == '\n': return r'\n'
    if ch == '\r': return r'\r'
    if ch in r"\.^$|?*+()[]{}": return '\\'+ch
    if ch == '-': return r'\-'
    return ch

def escape_class_char(ch):
    if ch == '\\': return r'\\'
    if ch == ']': return r'\]'
    if ch == '[': return r'\['
    if ch == '^': return r'\^'
    if ch == '-': return r'\-'
    if ch == '\t': return r'\t'
    if ch == '\n': return r'\n'
    if ch == '\r': return r'\r'
    return ch

def convert_char(ch, flags):
    if flags.get('digits') and is_decimal(ch):
        return r'\d'
    if flags.get('spaces') and is_space(ch):
        return r'\s'
    if flags.get('words') and is_word(ch):
        return r'\w'
    if flags.get('non_digits') and not is_decimal(ch):
        return r'\D'
    if flags.get('non_words') and not is_word(ch):
        return r'\W'
    if flags.get('non_spaces') and not is_space(ch):
        return r'\S'
    return None

def unicode_escape(ch, with_surrogates):
    code=ord(ch)
    if with_surrogates and code>=0x10000:
        high=0xD800+((code-0x10000)>>10)
        low=0xDC00+((code-0x10000)&0x3FF)
        return f"\\u{{{high:x}}}\\u{{{low:x}}}"
    else:
        return f"\\u{{{code:x}}}"

def transform_string(s, flags):
    toks=[]
    for ch in s:
        conv=convert_char(ch, flags)
        if conv is not None:
            toks.append(conv)
            continue
        if flags.get('escape') and ord(ch)>127:
            toks.append(unicode_escape(ch, flags.get('with_surrogates', False)))
            continue
        toks.append(escape_literal(ch))
    return toks

class Node:
    def __init__(self):
        self.children={}
        self.terminal=False

def build_trie(lists):
    root=Node()
    for toks in lists:
        node=root
        for t in toks:
            if t not in node.children:
                node.children[t]=Node()
            node=node.children[t]
        node.terminal=True
    return root

def charset_for_tokens(toks):
    orig=[]
    for tok in toks:
        if len(tok)==1: orig.append(tok)
        elif len(tok)==2 and tok[0]=='\\':
            esc=tok[1]
            if esc=='t': orig.append('\t')
            elif esc=='n': orig.append('\n')
            elif esc=='r': orig.append('\r')
            elif esc in '.^$|?*+()[]{}-\\': orig.append(esc)
            else: orig.append(esc)
        elif tok.startswith(r'\u{'):
            try:
                orig.append(chr(int(tok[tok.find('{')+1:tok.find('}')],16)))
            except: orig.append(tok)
        else: orig.append(tok)
    chars=sorted(orig, key=lambda c: ord(c))
    parts=[]
    i=0
    n=len(chars)
    while i<n:
        j=i
        while j+1<n and ord(chars[j+1])==ord(chars[j])+1:
            j+=1
        run=j-i+1
        if run>=3:
            parts.append(f"{escape_class_char(chars[i])}-{escape_class_char(chars[j])}")
