    if not lst: return ""
    pref=lst[0]
    for s in lst[1:]:
        i=0
        lim=min(len(pref), len(s))
        while i<lim and pref[i]==s[i]:
            i+=1
        pref=pref[:i]
        if not pref: break
    return pref

