                        k+=1
                res+=f"\x1b[1;36m]\x1b[0m"
                i=j+1
                continue
            else:
                res+=regex[i]
                i+=1
                continue
        if regex.startswith('(?:', i):
            res+=f"\x1b[1;32m(?:\x1b[0m"
            i+=3
            continue
        if regex[i]=='(' and (i+1>=n or regex[i+1]!='?'):
            res+=f"\x1b[1;32m(\x1b[0m"
            i+=1
            continue
        if regex[i]==')':
            res+=f"\x1b[1;32m)\x1b[0m"
            i+=1
            continue
        if regex[i]=='|':
            res+=f"\x1b[1;31m|\x1b[0m"
            i+=1
            continue
        if regex[i]=='?':
            res+=f"\x1b[1;35m?\x1b[0m"
            i+=1
            continue
        if regex[i]=='{':
            j=regex.find('}', i)
            if j!=-1:
                seg=regex[i:j+1]
                res+=f"\x1b[104;37m{seg}\x1b[0m"
                i=j+1
                continue
            else:
                res+=regex[i]
                i+=1
                continue
        if regex.startswith(r'\d', i) or regex.startswith(r'\D', i) or regex.startswith(r'\s', i) or regex.startswith(r'\S', i) or regex.startswith(r'\w', i) or regex.startswith(r'\W', i):
            seg=regex[i:i+2]
            res+=f"\x1b[103;30m{seg}\x1b[0m"
            i+=2
            continue
        if regex[i]=='\\' and i+1<n:
            if regex[i+1]=='u' and i+2<n and regex[i+2]=='{':
                j=regex.find('}', i)
                if j!=-1:
                    seg=regex[i:j+1]
                    res+=seg
                    i=j+1
                    continue
            res+=regex[i:i+2]
            i+=2
            continue
        res+=regex[i]
        i+=1
    return res

