    for ch in sorted(node.children.keys()):
        child=node.children[ch]
        cr=trie_to_regex(child, cap, flags)
        branches.append(ch+cr)
    has_empty=node.terminal
    if not branches:
        return ""
    if has_empty:
        if len(branches)==1:
            return make_opt(branches[0], cap)
        else:
            alt=branches_to_regex(branches, cap, flags)
            return make_opt(alt, cap)
    else:
        if len(branches)==1:
            return branches[0]
        else:
            return branches_to_regex(branches, cap, flags)

def generate_inner(cases, flags):
    token_lists=[transform_string(s, flags) for s in cases]
    if flags.get('repetitions'):
        min_rep=int(flags.get('min_repetitions','1'))
        min_len=int(flags.get('min_substring_length','1'))
        if len(token_lists)==1:
            toks=token_lists[0]
            n=len(toks)
            i=0
            comp=[]
            while i<n:
                best_len=0
                best_cnt=0
                maxL=n-i
                for L in range(min_len, maxL+1):
                    if i+L>n: break
                    pat=toks[i:i+L]
                    cnt=1
                    while i+cnt*L+L <= n and toks[i+cnt*L: i+(cnt+1)*L]==pat:
                        cnt+=1
                    if cnt-1 >= min_rep:
                        if cnt*L > (best_cnt*best_len if best_len else 0):
                            best_len=L
                            best_cnt=cnt
                if best_len:
                    pat_str=''.join(toks[i:i+best_len])
                    if best_len==1:
                        comp.append(f"{pat_str}{{{best_cnt}}}")
                    else:
                        comp.append(f"(?:{pat_str}){{{best_cnt}}}")
                    i+=best_len*best_cnt
                else:
                    comp.append(toks[i])
                    i+=1
            token_lists=[comp]
        else:
            sorted_lists=sorted(token_lists, key=len)
            pat=sorted_lists[0]
            pat_len=len(pat)
            if pat_len>=min_len:
                all_rep=True
                counts=[]
                for lst in token_lists:
                    if len(lst)%pat_len!=0:
                        all_rep=False
                        break
                    k=len(lst)//pat_len
                    if pat*k != lst:
                        all_rep=False
                        break
                    counts.append(k)
                if all_rep:
                    uniq_counts=sorted(set(counts))
                    is_consec = uniq_counts == list(range(min(uniq_counts), max(uniq_counts)+1))
                    pat_str=''.join(pat)
                    if is_consec:
                        mn=min(uniq_counts)
                        mx=max(uniq_counts)
                        if mx-1 >= min_rep:
                            if pat_len==1:
                                return f"{pat_str}{{{mn},{mx}}}" if mn!=mx else f"{pat_str}{{{mx}}}"
                            else:
                                if mn==1:
                                    return f"(?:{pat_str}|(?:{pat_str}){{{mn+1},{mx}}})"
                                else:
                                    return f"(?:{pat_str}){{{mn},{mx}}}"
                    else:
                        uniq_counts_sorted=sorted(set(counts))
                        runs=[]
                        cur=[uniq_counts_sorted[0]]
                        for c in uniq_counts_sorted[1:]:
                            if c==cur[-1]+1:
                                cur.append(c)
                            else:
                                runs.append(cur)
                                cur=[c]
                        runs.append(cur)
                        opts=[]
                        for run in runs:
                            mn_run=min(run)
                            mx_run=max(run)
                            if len(run)==1:
                                k=mn_run
                                if k==1:
                                    opts.append(pat_str)
                                else:
                                    if k-1 >= min_rep:
                                        if pat_len==1:
                                            opts.append(f"{pat_str}{{{k}}}")
                                        else:
                                            opts.append(f"(?:{pat_str}){{{k}}}")
                                    else:
                                        opts.append(pat_str * k)
                            else:
                                if mx_run-1 >= min_rep:
                                    if pat_len==1:
                                        opts.append(f"{pat_str}{{{mn_run},{mx_run}}}")
                                    else:
                                        if mn_run==1:
                                            opts.append(f"(?:{pat_str}|(?:{pat_str}){{{mn_run+1},{mx_run}}})")
                                        else:
                                            opts.append(f"(?:{pat_str}){{{mn_run},{mx_run}}}")
                                else:
                                    for k in run:
                                        opts.append(pat_str * k)
                        if len(opts)==1:
                            return opts[0]
                        pre='(' if flags.get('capture_groups') else '(?:'
                        return f"{pre}{'|'.join(opts)})"
            common=token_lists[0]
            for lst in token_lists[1:]:
                i=0
                while i < len(common) and i < len(lst) and common[i]==lst[i]:
                    i+=1
                common=common[:i]
            common_len=len(common)
            if common_len>0:
                suffixes=[lst[common_len:] for lst in token_lists]
                non_empty=[s for s in suffixes if s]
                if non_empty:
                    cand_pat=min(non_empty, key=len)
                    cand_len=len(cand_pat)
                    if cand_len>=min_len:
                        all_rep2=True
                        rep_counts=[]
                        for s in suffixes:
                            if len(s)%cand_len!=0:
                                all_rep2=False
                                break
                            k=len(s)//cand_len if cand_len else 0
                            if cand_pat * k != s:
                                all_rep2=False
                                break
                            rep_counts.append(k)
                        if all_rep2:
                            uniq_counts2=sorted(set(rep_counts))
                            is_consec2 = uniq_counts2 == list(range(min(uniq_counts2), max(uniq_counts2)+1))
                            if is_consec2:
                                max_k=max(rep_counts)
                                non_zero=[k for k in rep_counts if k>0]
                                if non_zero:
                                    mn=min(non_zero)
                                    mx=max(non_zero)
                                    if mx-1 >= min_rep and cand_len>=min_len:
                                        common_str=''.join(common)
                                        cand_str=''.join(cand_pat)
                                        if cand_len==1:
                                            if 0 in rep_counts:
                                                quant=f"{cand_str}{{{mn},{mx}}}" if mn!=mx else f"{cand_str}{{{mx}}}"
                                                quant_opt=make_opt(quant, flags.get('capture_groups', False))
                                                return common_str + quant_opt
                                            else:
                                                quant=f"{cand_str}{{{mn},{mx}}}"
                                                return common_str + quant
                            else:
                                has_zero = 0 in rep_counts
                                uniq_non_zero=sorted(set(k for k in rep_counts if k>0))
                                runs=[]
                                cur=[uniq_non_zero[0]]
                                for c in uniq_non_zero[1:]:
                                    if c==cur[-1]+1:
                                        cur.append(c)
                                    else:
                                        runs.append(cur)
                                        cur=[c]
                                runs.append(cur)
                                opts2=[]
                                cand_str=''.join(cand_pat)
                                for run in runs:
                                    mn_run=min(run)
                                    mx_run=max(run)
                                    if len(run)==1:
                                        k=mn_run
                                        if k-1 >= min_rep:
                                            if cand_len==1:
                                                opts2.append(f"{cand_str}{{{k}}}")
                                            else:
                                                opts2.append(f"(?:{cand_str}){{{k}}}")
                                        else:
                                            opts2.append(cand_str * k)
                                    else:
                                        if mx_run-1 >= min_rep:
                                            if cand_len==1:
                                                opts2.append(f"{cand_str}{{{mn_run},{mx_run}}}")
                                            else:
                                                if mn_run==1:
                                                    opts2.append(f"(?:{cand_str}|(?:{cand_str}){{{mn_run+1},{mx_run}}})")
                                                else:
                                                    opts2.append(f"(?:{cand_str}){{{mn_run},{mx_run}}}")
                                        else:
                                            for k in run:
                                                opts2.append(cand_str * k)
                                if not opts2:
                                    return ''.join(common)
                                if len(opts2)==1:
                                    suffix_inner=opts2[0]
                                else:
                                    pre2='(' if flags.get('capture_groups') else '(?:'
                                    suffix_inner=f"{pre2}{'|'.join(opts2)})"
                                common_str=''.join(common)
                                if has_zero:
                                    suffix_inner_opt=make_opt(suffix_inner, flags.get('capture_groups', False))
                                    return common_str + suffix_inner_opt
                                else:
                                    return common_str + suffix_inner
    root=build_trie(token_lists)
    return trie_to_regex(root, flags.get('capture_groups', False), flags)

def colorize_regex(regex):
    res=""
    i=0
    n=len(regex)
    while i < n:
        if regex.startswith('(?', i):
            end=regex.find(')', i)
            if end!=-1:
                seg=regex[i:end+1]
                res+=f"\x1b[40;93m{seg}\x1b[0m"
                i=end+1
                continue
        if regex[i] in ('^','$'):
            res+=f"\x1b[1;33m{regex[i]}\x1b[0m"
            i+=1
            continue
        if regex[i]=='[':
            j=regex.find(']', i)
            if j!=-1:
                res+=f"\x1b[1;36m[\x1b[0m"
                inner=regex[i+1:j]
                k=0
                while k < len(inner):
                    if inner[k]=='-':
                        res+=f"\x1b[1;36m-\x1b[0m"
                        k+=1
                    elif inner[k]=='\\' and k+1 < len(inner):
                        res+=inner[k:k+2]
                        k+=2
                    else:
                        res+=inner[k]
                        k+=1
                res+=f"\x1b[1;36m]\x1b[0m"
                i=j+1
                continue
            else:
                res+=regex[i]
                i+=1
                continue
        if regex.startswith('(?:', i):
            res+=f"\x1b[1;32m(?:\x1b[0m"
            i+=3
            continue
        if regex[i]=='(' and (i+1>=n or regex[i+1]!='?'):
            res+=f"\x1b[1;32m(\x1b[0m"
            i+=1
            continue
        if regex[i]==')':
            res+=f"\x1b[1;32m)\x1b[0m"
            i+=1
            continue
        if regex[i]=='|':
            res+=f"\x1b[1;31m|\x1b[0m"
            i+=1
            continue
        if regex[i]=='?':
            res+=f"\x1b[1;35m?\x1b[0m"
            i+=1
            continue
        if regex[i]=='{':
            j=regex.find('}', i)
            if j!=-1:
                seg=regex[i:j+1]
                res+=f"\x1b[104;37m{seg}\x1b[0m"
                i=j+1
                continue
            else:
                res+=regex[i]
                i+=1
                continue
        if regex.startswith(r'\d', i) or regex.startswith(r'\D', i) or regex.startswith(r'\s', i) or regex.startswith(r'\S', i) or regex.startswith(r'\w', i) or regex.startswith(r'\W', i):
            seg=regex[i:i+2]
            res+=f"\x1b[103;30m{seg}\x1b[0m"
            i+=2
            continue
        if regex[i]=='\\' and i+1<n:
            if regex[i+1]=='u' and i+2<n and regex[i+2]=='{':
                j=regex.find('}', i)
                if j!=-1:
                    seg=regex[i:j+1]
                    res+=seg
                    i=j+1
                    continue
            res+=regex[i:i+2]
            i+=2
            continue
        res+=regex[i]
        i+=1
    return res

